"use client";

import { useState } from "react";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  CreditCardIcon,
  MoreVerticalIcon,
  PencilEdit01Icon,
  Tick02Icon,
  Delete02Icon,
  Cancel01Icon,
} from "@hugeicons/core-free-icons";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { cn } from "@/lib/utils";
import { AddPaymentDialog } from "./add-payment-dialog";
import { EditPaymentDialog } from "./edit-payment-dialog";
import { PaymentMethod } from "@/types/payment";

const DEFAULT_METHODS: PaymentMethod[] = [
  {
    id: "1",
    type: "visa",
    last4: "4242",
    expiryMonth: 12,
    expiryYear: 2026,
    isDefault: true,
  },
  {
    id: "2",
    type: "mastercard",
    last4: "8888",
    expiryMonth: 8,
    expiryYear: 2025,
    isDefault: false,
  },
];

const PAYMENT_LOGOS: Record<string, string> = {
  visa: "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/ecommerce/payment-methods/visa.svg",
  mastercard:
    "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/ecommerce/payment-methods/mastercard.svg",
  amex: "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/ecommerce/payment-methods/amex.svg",
  paypal:
    "https://deifkwefumgah.cloudfront.net/shadcnblocks/block/ecommerce/payment-methods/paypal.svg",
};

interface PaymentMethodsProps {
  methods?: PaymentMethod[];
  className?: string;
}

const PaymentMethods = ({
  methods: initialMethods = DEFAULT_METHODS,
  className,
}: PaymentMethodsProps) => {
  const [methods, setMethods] = useState(initialMethods);
  const [selectedId, setSelectedId] = useState(
    methods.find((m) => m.isDefault)?.id || methods[0]?.id,
  );

  const deleteMethod = (id: string) => {
    const newMethods = methods.filter((method) => method.id !== id);
    setMethods(newMethods);
    if (selectedId === id && newMethods.length > 0) {
      setSelectedId(newMethods[0].id);
    }
  };

  const updateMethod = (updated: PaymentMethod) => {
    setMethods((prev) =>
      prev.map((m) => (m.id === updated.id ? updated : m))
    );
  };

  return (
    <section className={cn("w-full", className)}>
      <div className="w-full">
        {/* Header */}
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h2 className="text-xl font-semibold tracking-tight">
              Payment Methods
            </h2>
            <p className="text-sm text-muted-foreground">
              Manage your saved payment methods
            </p>
          </div>
          <AddPaymentDialog
            onAdd={(newMethod) => {
              setMethods((prev) => [...prev, newMethod]);
              if (methods.length === 0) setSelectedId(newMethod.id);
            }}
            isFirstCard={methods.length === 0}
          />
        </div>

        {/* Payment Methods List */}
        <RadioGroup value={selectedId} onValueChange={setSelectedId}>
          <div className="space-y-3">
            {methods.map((method) => (
              <Card
                key={method.id}
                className={cn(
                  "cursor-pointer transition-colors border-border/40 hover:border-border",
                  selectedId === method.id && "border-primary bg-primary/5",
                )}
                onClick={() => setSelectedId(method.id)}
              >
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    <RadioGroupItem value={method.id} id={method.id} />

                    {/* Payment Logo */}
                    <div className="flex size-10 items-center justify-center rounded-lg border border-border/50 bg-muted/40 p-1">
                      {PAYMENT_LOGOS[method.type] ? (
                        <img
                          src={PAYMENT_LOGOS[method.type]}
                          alt={method.type}
                          className="h-full w-full object-contain"
                        />
                      ) : (
                        <HugeiconsIcon icon={CreditCardIcon} className="size-5 text-muted-foreground" />
                      )}
                    </div>

                    {/* Details */}
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-medium">
                          {method.type === "paypal"
                            ? "PayPal"
                            : `${method.type.charAt(0).toUpperCase() + method.type.slice(1)} •••• ${method.last4}`}
                        </span>
                        {method.isDefault && (
                          <Badge variant="outline" className="text-[10px] font-medium h-5">
                            Default
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {method.type === "paypal"
                          ? method.email
                          : `Expires ${method.expiryMonth}/${method.expiryYear}`}
                      </p>
                    </div>

                    {/* Actions - Visible côte à côte */}
                    <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
                      <EditPaymentDialog 
                        method={method} 
                        onUpdate={updateMethod} 
                      />

                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button 
                            variant="ghost" 
                            size="icon" 
                            className="size-8 text-muted-foreground hover:text-destructive hover:bg-destructive/10"
                          >
                            <HugeiconsIcon icon={Delete02Icon} className="size-4" />
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent className="border-border/50 bg-muted/20 backdrop-blur-xl">
                          <AlertDialogHeader>
                            <AlertDialogTitle className="text-xl font-bold">Remove Payment Method</AlertDialogTitle>
                            <AlertDialogDescription className="text-muted-foreground">
                              Are you sure you want to remove this card? This action cannot be undone.
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel className="bg-background/50 border-border/50">Cancel</AlertDialogCancel>
                            <AlertDialogAction 
                              onClick={() => deleteMethod(method.id)}
                              className="bg-destructive text-destructive-foreground hover:bg-destructive/90 shadow-lg shadow-destructive/20"
                            >
                              Remove Card
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </RadioGroup>

        {methods.length === 0 && (
          <Card className="border-dashed border-2 bg-muted/20">
            <CardContent className="flex flex-col items-center justify-center py-12 text-center">
              <div className="rounded-full bg-muted p-4 mb-4">
                <HugeiconsIcon icon={CreditCardIcon} className="size-8 text-muted-foreground" />
              </div>
              <h2 className="text-xl font-semibold">No payment methods</h2>
              <p className="mt-2 text-muted-foreground max-w-[250px]">
                Add a payment method for faster checkout and plan management.
              </p>
              <div className="mt-6">
                <AddPaymentDialog
                  onAdd={(newMethod) => {
                    setMethods([newMethod]);
                    setSelectedId(newMethod.id);
                  }}
                  isFirstCard
                />
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </section>
  );
};

export { PaymentMethods };
